package com.example.uniride.backend.user;

import jakarta.persistence.Column;
import jakarta.persistence.Embedded;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;

import java.time.Instant;
import java.util.UUID;

/**
 * Registered student. The id is generated by the server (docs/API.md §1). Never returned
 * by a controller: it is mapped to a {@code *Response}.
 */
@Entity
@Table(name = "users")
public class User {

    @Id
    private UUID id;

    @Column(nullable = false, unique = true, length = 120)
    private String email;

    @Column(name = "password_hash", nullable = false, length = 100)
    private String passwordHash;

    @Column(name = "full_name", nullable = false, length = 100)
    private String fullName;

    @Column(nullable = false, length = 100)
    private String career;

    @Column(nullable = false, length = 30)
    private String phone;

    @Enumerated(EnumType.STRING)
    @Column(name = "preferred_mode", nullable = false, length = 20)
    private PreferredMode preferredMode;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private AccountStatus status;

    /** {@code null} while nobody rated the user. */
    @Column(name = "rating_avg")
    private Double ratingAvg;

    @Column(name = "rating_count", nullable = false)
    private int ratingCount;

    /** {@code null} if the user did not load a vehicle. */
    @Embedded
    private Vehicle vehicle;

    @CreationTimestamp
    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @UpdateTimestamp
    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    protected User() {
    }

    /** New account, {@code PENDIENTE} until activated (RF01). */
    public User(String email, String passwordHash, String fullName, String career, String phone,
                PreferredMode preferredMode, Vehicle vehicle) {
        this.id = UUID.randomUUID();
        this.email = email;
        this.passwordHash = passwordHash;
        this.fullName = fullName;
        this.career = career;
        this.phone = phone;
        this.preferredMode = preferredMode;
        this.vehicle = vehicle;
        this.status = AccountStatus.PENDIENTE;
        this.ratingCount = 0;
    }

    public UUID getId() {
        return id;
    }

    public String getEmail() {
        return email;
    }

    public String getPasswordHash() {
        return passwordHash;
    }

    public void setPasswordHash(String passwordHash) {
        this.passwordHash = passwordHash;
    }

    public String getFullName() {
        return fullName;
    }

    public void setFullName(String fullName) {
        this.fullName = fullName;
    }

    public String getCareer() {
        return career;
    }

    public void setCareer(String career) {
        this.career = career;
    }

    public String getPhone() {
        return phone;
    }

    public void setPhone(String phone) {
        this.phone = phone;
    }

    public PreferredMode getPreferredMode() {
        return preferredMode;
    }

    public void setPreferredMode(PreferredMode preferredMode) {
        this.preferredMode = preferredMode;
    }

    public AccountStatus getStatus() {
        return status;
    }

    public void activate() {
        this.status = AccountStatus.ACTIVA;
    }

    public boolean isActive() {
        return status == AccountStatus.ACTIVA;
    }

    public Double getRatingAvg() {
        return ratingAvg;
    }

    public int getRatingCount() {
        return ratingCount;
    }

    public Vehicle getVehicle() {
        return vehicle;
    }

    public void setVehicle(Vehicle vehicle) {
        this.vehicle = vehicle;
    }

    public boolean hasVehicle() {
        return vehicle != null && vehicle.getPlate() != null;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    /** "Lucía F.": how other users see this one (RNF07, docs/API.md §3.2). */
    public String getPublicName() {
        String[] parts = fullName.trim().split("\\s+");
        if (parts.length < 2) {
            return parts[0];
        }
        return parts[0] + " " + parts[parts.length - 1].charAt(0) + ".";
    }
}
